import{_ as i,o as n,c as t,a2 as r}from"./chunks/framework.7R1OEGYz.js";const s="/docs/images/manual/arus.png",e="/docs/images/manual/arus-fasa.png",o="/docs/images/manual/mobile-arus.png",f=JSON.parse('{"title":"5. Monitoring Arus","description":"Pencatatan beban arus (Ampere) setiap penyulang tiap 30 menit.","frontmatter":{"title":"5. Monitoring Arus","description":"Pencatatan beban arus (Ampere) setiap penyulang tiap 30 menit."},"headers":[],"relativePath":"monitoring-arus.md","filePath":"monitoring-arus.md"}'),l={name:"monitoring-arus.md"};function u(g,a,p,m,d,c){return n(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="_5-monitoring-arus" tabindex="-1">5. Monitoring Arus <a class="header-anchor" href="#_5-monitoring-arus" aria-label="Permalink to &quot;5. Monitoring Arus&quot;">​</a></h1><p>Pencatatan beban arus (Ampere) setiap penyulang tiap 30 menit. <span class="manual-badge">Akses: Lihat Monitoring Arus</span></p><h2 id="filter-tampilan" tabindex="-1">Filter &amp; tampilan <a class="header-anchor" href="#filter-tampilan" aria-label="Permalink to &quot;Filter &amp; tampilan&quot;">​</a></h2><ul><li><strong>Tanggal</strong>: pilih tanggal pencatatan.</li><li><strong>Shift</strong>: Pagi, Sore, atau Malam. Setiap shift berisi 16 interval (mis. shift pagi 08.30 s.d. 16.00).</li><li><strong>Beban penyulang</strong>: grafik garis dan tabel isian arus per penyulang per interval.</li><li><strong>Arus per fasa</strong>: tabel arus tiap fasa yang dihitung otomatis dari data penyulang (hanya baca).</li></ul><figure class="manual-figure"><p><img src="'+s+'" alt="Monitoring Arus: filter tanggal &amp; shift, grafik tren, dan tabel isian per interval."></p><figcaption>Monitoring Arus: filter tanggal &amp; shift, grafik tren, dan tabel isian per interval.</figcaption></figure><h2 id="menginput-arus-perlu-izin-input-edit-monitoring-arus" tabindex="-1">Menginput arus <span class="manual-badge">Perlu izin: Input/Edit Monitoring Arus</span> <a class="header-anchor" href="#menginput-arus-perlu-izin-input-edit-monitoring-arus" aria-label="Permalink to &quot;Menginput arus &lt;span class=&quot;manual-badge&quot;&gt;Perlu izin: Input/Edit Monitoring Arus&lt;/span&gt;&quot;">​</a></h2><ol><li>Pilih <strong>tanggal</strong> dan <strong>shift</strong> yang akan diisi.</li><li>Pada tabel <strong>Beban arus per interval</strong>, isi nilai Ampere setiap penyulang di baris jam yang sesuai.</li><li>Tekan <strong>Simpan</strong> di ujung baris untuk menyimpan satu jam, atau isi beberapa baris lalu tekan <strong>Simpan semua</strong> di atas tabel.</li><li>Tunggu notifikasi berhasil. Grafik dan Dashboard akan langsung diperbarui.</li></ol><figure class="manual-figure"><p><img src="'+e+'" alt="Tab Arus per fasa: dihitung otomatis dari data penyulang."></p><figcaption>Tab Arus per fasa: dihitung otomatis dari data penyulang.</figcaption></figure><p><span class="manual-badge">Perlu izin: Input/Edit Monitoring Arus</span></p><div class="warning custom-block"><p class="custom-block-title">Perhatian</p><p>Baris yang sudah diubah tetapi belum disimpan ditandai &quot;baris belum disimpan&quot;. Jika Anda pindah tanggal, shift, atau menu, aplikasi akan meminta konfirmasi karena isian tersebut akan hilang.</p></div><p>Di ponsel, tabel ditampilkan sebagai kartu per jam. Tombol <strong>Simpan jam ...</strong> ada di setiap kartu dan tombol <strong>Simpan semua</strong> menempel di atas layar saat digulir.</p><figure class="manual-figure is-mobile"><p><img src="'+o+'" alt="Monitoring Arus di ponsel."></p><figcaption>Monitoring Arus di ponsel.</figcaption></figure>',12)])])}const h=i(l,[["render",u]]);export{f as __pageData,h as default};
